// The vendored API schema of the pinned version (generated by npm run api:vendor,
// tools/src/openapi/vendor.ts; format in docs/ARCHITECTURE.md §4.6). Parsed on first use and kept
// as a derived cache outside world state (docs/ARCHITECTURE.md §2.12): it is static data.

import { DATA } from './data/v1.37.2.ts';

/** A Go type expression: what encoding/json decodes into and encodes from. */
export type TypeExpr =
  | { k: 'basic'; name: string }
  | { k: 'bytes' }
  | { k: 'any' }
  | { k: 'ptr'; elem: TypeExpr }
  | { k: 'slice'; elem: TypeExpr }
  | { k: 'map'; key: TypeExpr; elem: TypeExpr }
  | { k: 'named'; id: string };

export interface FieldSpec {
  json: string;
  type: TypeExpr;
  omitempty: boolean;
  omitzero: boolean;
  /** OpenAPI `required` of the enclosing definition. */
  required: boolean;
  listType?: 'atomic' | 'set' | 'map';
  listMapKeys?: string[];
  mapType?: string;
  patchStrategy?: string;
  patchMergeKey?: string;
  enum?: string[];
}

export type CustomKind = 'time' | 'microtime' | 'duration' | 'json' | 'string' | 'quantity' | 'intstr';

export interface NamedType {
  id: string;
  /** What Go's reflect prints: `v1.PodSpec`. */
  display: string;
  /** The type name alone: `PodSpec`, the `Struct` of a json.UnmarshalTypeError. */
  name: string;
  /** The OpenAPI definition, for structs that have one: `io.k8s.api.core.v1.PodSpec`. */
  definition?: string;
  struct?: { fields: FieldSpec[]; byJson: Record<string, FieldSpec> };
  /** A defined non-struct type: `type RestartPolicy string`. */
  underlying?: TypeExpr;
  /** A type with its own MarshalJSON/UnmarshalJSON. */
  custom?: CustomKind;
}

interface RawData {
  version: string;
  kinds: Record<string, string>;
  types: Record<string, { n: string; d?: string; c?: CustomKind; u?: string; f?: (string | Record<string, unknown>)[][] }>;
}

export interface Schema {
  version: string;
  /** `apps/v1/Deployment` → its type. */
  kind(apiVersion: string, kind: string): NamedType | undefined;
  type(id: string): NamedType;
  kinds(): string[];
}

/** Parses `[]@core/v1.Container`, `map[string]string`, `*int32`, `bytes`. */
export function parseTypeExpr(s: string): TypeExpr {
  const [e, rest] = parseAt(s);
  if (rest !== '') throw new Error(`trailing text in type ${s}`);
  return e;
}

function parseAt(s: string): [TypeExpr, string] {
  if (s.startsWith('*')) {
    const [elem, rest] = parseAt(s.slice(1));
    return [{ k: 'ptr', elem }, rest];
  }
  if (s.startsWith('[]')) {
    const [elem, rest] = parseAt(s.slice(2));
    return [{ k: 'slice', elem }, rest];
  }
  if (s.startsWith('map[')) {
    const [key, r1] = parseAt(s.slice(4));
    if (!r1.startsWith(']')) throw new Error(`bad map type ${s}`);
    const [elem, rest] = parseAt(r1.slice(1));
    return [{ k: 'map', key, elem }, rest];
  }
  const m = /^(@[\w./-]+|[a-z0-9]+)/.exec(s);
  if (!m) throw new Error(`bad type ${s}`);
  const tok = m[1] as string;
  const rest = s.slice(tok.length);
  if (tok.startsWith('@')) return [{ k: 'named', id: tok.slice(1) }, rest];
  if (tok === 'bytes') return [{ k: 'bytes' }, rest];
  if (tok === 'any') return [{ k: 'any' }, rest];
  return [{ k: 'basic', name: tok }, rest];
}

function build(): Schema {
  const raw = JSON.parse(DATA) as RawData;
  const cache: Record<string, NamedType> = {};
  const type = (id: string): NamedType => {
    const hit = cache[id];
    if (hit) return hit;
    const t = raw.types[id];
    if (!t) throw new Error(`schema has no type ${id}`);
    const name = t.n.slice(t.n.indexOf('.') + 1);
    const out: NamedType = { id, display: t.n, name, ...(t.d ? { definition: t.d } : {}) };
    if (t.c) out.custom = t.c;
    else if (t.u) out.underlying = parseTypeExpr(t.u);
    else {
      const fields: FieldSpec[] = (t.f ?? []).map((row) => {
        const [json, ty, flags = '', extra = {}] = row as [string, string, string?, Record<string, unknown>?];
        const f: FieldSpec = {
          json,
          type: parseTypeExpr(ty),
          omitempty: flags.includes('o'),
          omitzero: flags.includes('z'),
          required: flags.includes('r'),
        };
        if (extra.lt) f.listType = extra.lt as FieldSpec['listType'] & string;
        if (extra.lk) f.listMapKeys = extra.lk as string[];
        if (extra.mt) f.mapType = extra.mt as string;
        if (extra.ps) f.patchStrategy = extra.ps as string;
        if (extra.pk) f.patchMergeKey = extra.pk as string;
        if (extra.en) f.enum = extra.en as string[];
        return f;
      });
      const byJson: Record<string, FieldSpec> = Object.create(null) as Record<string, FieldSpec>;
      for (const f of fields) byJson[f.json] = f;
      out.struct = { fields, byJson };
    }
    cache[id] = out;
    return out;
  };
  return {
    version: raw.version,
    kind: (apiVersion, kind) => {
      const id = raw.kinds[`${apiVersion}/${kind}`];
      return id === undefined ? undefined : type(id);
    },
    type,
    kinds: () => Object.keys(raw.kinds),
  };
}

let loaded: Schema | undefined;

/** The schema of the pinned version, parsed on first call. */
export function schema(): Schema {
  loaded ??= build();
  return loaded;
}

/** reflect.Type.String() of an expression, as encoding/json prints it in errors. */
export function displayType(t: TypeExpr): string {
  switch (t.k) {
    case 'basic':
      return t.name;
    case 'bytes':
      return '[]uint8';
    case 'any':
      return 'interface {}';
    case 'ptr':
      return '*' + displayType(t.elem);
    case 'slice':
      return '[]' + displayType(t.elem);
    case 'map':
      return `map[${displayType(t.key)}]${displayType(t.elem)}`;
    case 'named':
      return schema().type(t.id).display;
  }
}
